-- Stores artifacts generated by the AI SearchLens Fixer tab —
-- llms.txt, robots.txt, FAQ schema JSON-LD, citable answer blocks, and
-- title/meta variants. Single-tenant org default keeps writes simple;
-- history view filters by kind.

create table if not exists public.ais_fix_artifacts (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default 'a0000000-0000-0000-0000-000000000001'::uuid,
  kind text not null check (kind in ('llms_txt','robots_txt','schema_jsonld','answer_block','meta_rewrite')),
  title text not null,
  input_json jsonb not null default '{}'::jsonb,
  output_text text not null,
  output_format text not null default 'text' check (output_format in ('text','html','jsonld','markdown')),
  deployment_target text,
  source_url text,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists ais_fix_artifacts_kind_idx
  on public.ais_fix_artifacts(kind, created_at desc);
create index if not exists ais_fix_artifacts_source_url_idx
  on public.ais_fix_artifacts(source_url) where source_url is not null;

create or replace function public.touch_ais_fix_artifacts_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end; $$;

drop trigger if exists ais_fix_artifacts_touch on public.ais_fix_artifacts;
create trigger ais_fix_artifacts_touch before update on public.ais_fix_artifacts
  for each row execute function public.touch_ais_fix_artifacts_updated_at();

alter table public.ais_fix_artifacts enable row level security;
drop policy if exists "ais_fix_artifacts org access" on public.ais_fix_artifacts;
create policy "ais_fix_artifacts org access" on public.ais_fix_artifacts
  for all using (true) with check (true);

alter publication supabase_realtime add table public.ais_fix_artifacts;
